"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Her oda: seferlere {0} kalıntı fazla. “Savunma” uyumu: silahlar +%{1} hasar verir, isabette sıçrar ve yavaşlatır; diğerleri {2} nöbetçi daha.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Her oda: getirilen erzak +%{0}. “Talih” uyumu: erzak ek +%{1}, her savaş başlangıç puan çarpanı +{2}.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Her oda: sefer görüşü +{0}, başlangıç puan çarpanı +{1}. “Talih / Özel” uyumu: sefer haritası baştan tamamen açık, çarpan ek +{2}.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Her oda: sefer birliklerinin saldırısı +%{0}. “Eğitim” uyumu: liderin sefer XP'si +%{1}.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Her oda: sefer birliklerinin canı +%{0}. “Sağlık” uyumu: hastane iyileştirmesi +%{1}, lider günde ek %{2} iyileşir.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Her oda: plan düşme oranı +%{0}. “Bilimkurgu” uyumu: üs günde +{1} Ruh Parçası.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Her oda: plan düşme oranı +%{0}. “Demircilik” uyumu: dövmede %{1} ihtimalle bir kalıntı daha.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Her oda: üs günde +{0} Ruh Parçası. “Büyü” uyumu: günde ek +{1}.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Her oda: üs günde +{0} erzak. “Lojistik” uyumu: bu odanın kendi etkisi ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Her oda: üs günde +{0} erzak, lider günde {1} XP kazanır. “Lojistik / Doğa” uyumu: bu odanın kendi etkisi ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Her oda: kalıntı dövme maliyeti -%{0}. “Demircilik / Silah” uyumu: dövmede %{1} ihtimalle kalite +{2}; silahlar +%{3} hasar verir.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Her oda: inşa süresi yarıya iner, bitince erzağın %{0} kadarı iade edilir. “Harika” uyumu: iade %{1} olur.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Her oda: tüm savunma kuleleri +%{0} hasar verir. “Silah” uyumu: menzil +{1}, saldırı hızı +%{2}.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Her oda: kazı maliyeti -%{0}. “Özel” uyumu: tüm inşaatlar {1} gün kısa sürer.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Her oda: her savaş başlangıç puan çarpanı +{0}. “Demircilik” uyumu: dövülen kalıntılar her zaman +{1} kalite.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Her oda: lider becerisi bekleme süresi {0} durak kısa. “Talih” uyumu: seferlere {1} ek destek eşyasıyla başla (en az “Epik” etki).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Her oda: lider saldırısı +%{0}. “Silah” uyumu: hasar +%{1}, her saldırı zincirleme yıldırım salar ({2} düşmana sıçrar).",
