"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Her oda: liderin günde {0} XP kazanır. “Üretim” uyumu: bu odanın kendi üretimi ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Her oda: liderin günde {0} XP kazanır. “Eğitim” uyumu: liderin sefer XP'si +%{1}.",
